TITLES=['Tóm tắt nghiên cứu','Baseline ICT hiện có','Định nghĩa các mô hình ICT','Nguồn và phạm vi dữ liệu','Số lượng mẫu hình','So sánh Win Rate tổng thể','Win Rate theo công cụ','Win Rate theo hướng','Win Rate theo phiên','Kết quả theo tháng và năm','Khoảng tin cậy Win Rate','Kỳ vọng trước và sau phí','Profit Factor giả định','Đường kết quả R cộng dồn','Drawdown mô phỏng','So sánh thống kê','Phân tích Bootstrap','Ví dụ nến lịch sử','Kiểm định theo thời gian','Giới hạn nghiên cứu','Bảng so sánh thống kê cuối cùng']

def generate(root):
    out=root/'reports/multi_model';read=lambda name:json.loads((out/name).read_text(encoding='utf-8'))
    totals=read('summary.json');groups=read('groups.json');coverage=read('coverage.json');contrasts=read('contrasts.json')
    sim=pd.read_parquet(out/'simulations.parquet');patterns=pd.read_parquet(out/'patterns.parquet')
    formations=pd.read_parquet(out/'formations.parquet');rejects=pd.read_parquet(out/'rejected.parquet')
    charts=[];sections={};colors=['#182a2b','#146f64','#b67b23','#597891','#a45148']
    def chart(fig,name):
        cid=f'chart-{len(charts)}'
        fig.update_layout(template='plotly_white',font=dict(family='Segoe UI',color='#182a2b'),paper_bgcolor='rgba(0,0,0,0)',plot_bgcolor='rgba(0,0,0,0)',margin=dict(l=60,r=24,t=65,b=80),height=430,title=name,legend=dict(orientation='h',y=-.25),colorway=colors)
        charts.append({'id':cid,'figure':json.loads(pio.to_json(fig))})
        return f'<div class="chart" id="{cid}" aria-label="{html.escape(name)}"></div>'
    def table(rows):
        return '<div class="table-scroll">'+pd.DataFrame(rows).to_html(index=False,escape=True,classes='data-table',border=0,na_rep='—')+'</div>'
    def num(v,n=3):return '—' if v is None or not np.isfinite(v) else f'{v:,.{n}f}'
    def pct(v):return '—' if v is None else f'{100*v:.2f}%'
    def interval(s):
        c=s['wilson']['95'];return f'{pct(c["low"])} – {pct(c["high"])}'
    def compact(s):
        return {'Track':s['track'],'Mô hình':NAMES[s['model']],'Mẫu':s['patterns'],'n resolved':s['resolved'],'Wins':s['wins'],'Losses':s['losses'],'Unresolved':s['unresolved'],'Ambiguous':s['ambiguous'],'Invalid':s['invalid'],'WR (n resolved)':f'{pct(s["win_rate"])} (n={s["resolved"]:,})','CI95 Wilson':interval(s),'Gross E (R)':num(s['gross']['expectancy_r']),'Net E (R)':num(s['cost_adjusted']['expectancy_r'])}
    b=[s for s in totals if s['track']=='B'];a=[s for s in totals if s['track']=='A']
    sections[1]='<p class="lead">Năm mô hình · cùng dữ liệu · hai quy ước đầu ra</p><p>So sánh lịch sử trên Binance USD-M perpetual M5. Bảng chính dùng Track B: RR 1:2, vào open sau xác nhận, phí giả định 10 bps và horizon 288 nến. Không có giao dịch thực.</p>'+table([compact(s) for s in b])+'<p>WR = Wins / (Wins + Losses). Các mẫu chưa phân giải, ambiguous và invalid được giữ riêng. Kỳ vọng chỉ tính kết quả đã phân giải; censoring có thể gây thiên lệch. Không kết luận lợi nhuận tương lai.</p>'
    old=json.loads((root/'reports/results/statistical_analysis.json').read_text(encoding='utf-8'))['overall']
    sections[2]=f'<p>Snapshot gốc: <strong>{old["patterns"]:,} mẫu; {pct(old["win_rate"])} (n={old["resolved"]:,})</strong>, CI95 {interval(old)}. Không sửa detector, simulator, báo cáo hay kết quả gốc. M0 Track B được chạy lại và đối soát từng outcome, gross/net R, entry/exit timestamp.</p><p>Baseline: swing ba nến → sweep đúng màu → MSS → FVG trong đoạn sweep–MSS; không Daily Bias. Mẫu M0 xác nhận tại MSS close; M1/M2/M4 xác nhận tại revisit close. Cùng quy tắc next-open nhưng thời điểm kinh tế khác nhau.</p>'
    negative=sum(s['cost_adjusted']['expectancy_r'] is not None and s['cost_adjusted']['expectancy_r']<0 for s in b)
    sections[1]+=f'<p><strong>{negative}/5 mô hình có kỳ vọng Net R âm trong Track B</strong> với chi phí giả định đã chọn. WR cao hơn không đồng nghĩa kỳ vọng sau phí cao hơn; quy mô mẫu và phân phối risk-distance khác nhau giữa mô hình.</p>'
    protocol=(root/'docs/MULTI_MODEL_PROTOCOL.md').read_text(encoding='utf-8-sig')
    sections[3]='<details><summary>Đặc tả đã khóa, nguồn tham khảo và các quy ước thực nghiệm</summary><pre class="prose">'+html.escape(protocol)+'</pre></details><p>Nguồn khái niệm: <a href="https://www.youtube.com/watch?v=Bkt8B3kLATQ">ICT 2022 Episode 6</a>, <a href="https://www.youtube.com/watch?v=tRq1hyGGtl4">ICT Silver Bullet</a>, <a href="https://www.youtube.com/watch?v=UrS-mtGHtAA">ICT Breaker Block</a>. Đã xác minh metadata, không xác thực toàn bộ transcript. Các ngưỡng số và lựa chọn breaker một nến là thí nghiệm của nghiên cứu này.</p>'
    sections[4]=table([{'Mã':c['symbol'],'Nến dùng':c['validated_candles'],'Từ UTC':c['earliest_timestamp'],'Đến UTC':c['latest_timestamp'],'Nến thiếu':c['missing_candles'],'Gaps':c['gap_count'],'Trùng':c['duplicate_candles'],'Nến volume=0':c['zero_volume_candles']} for c in coverage])+'<p>Nguồn: <a href="https://github.com/binance/binance-public-data">Binance Public Data</a>; manifest gốc được lưu bản sao cùng kết quả. Không tải lại dữ liệu. XAUUSDT chỉ từ 05/01/2026; không thay bằng vàng vật chất hoặc mã khác. M1 chỉ là cache được tải ở nghiên cứu trước: độ bao phủ không đồng đều giữa mô hình.</p>'+table(sim.groupby(['track','model','resolution','outcome']).size().rename('Số lượng').reset_index().to_dict('records'))
    counts=[]
    for m in range(5):
        counts.append({'Mô hình':NAMES[m],'Formation đủ điều kiện chờ revisit':int((formations.model==m).sum()) if m in [1,2,4] else 'Không áp dụng','Mẫu xác nhận cuối':int((patterns.model==m).sum()),'Ứng viên bị loại':int((rejects.model==m).sum())})
    sections[5]=table(counts)+'<p>Formation chưa revisit bị ghi ở rejection, không được tính là mẫu xác nhận cuối. Rejections bao gồm ứng viên chưa đủ displacement/geometry và setup hết hạn; mẫu số ứng viên khác nhau giữa mô hình, không dùng để xếp hạng tỷ lệ nhận diện.</p><details><summary>Chi tiết lý do loại</summary>'+table(rejects.groupby(['model','reason']).size().rename('count').reset_index().to_dict('records'))+'</details>'
    sections[6]='<div class="controls"><label>Track <select id="track"><option value="B">B — RR 1:2 chuẩn hóa</option><option value="A">A — Mục tiêu riêng</option></select></label><label>Phân nhóm <select id="dimension">'+''.join(f'<option value="{v}">{label}</option>' for v,label in [('symbol','Công cụ'),('direction','Hướng'),('session','Phiên thị trường'),('session_sb','Phiên Silver Bullet'),('hour','Giờ UTC'),('weekday','Thứ UTC'),('month','Tháng UTC'),('year','Năm UTC'),('partition','Partition'),('volatility','Biến động'),('fvg_relative','FVG/giá'),('sweep_relative','Sweep/giá'),('common_calendar','Cùng khoảng lịch')])+'</select></label><label>Mô hình <select id="model">'+''.join(f'<option value="{m}">{name}</option>' for m,name in NAMES.items())+'</select></label></div><p>Bộ lọc chỉ thay đổi hai biểu đồ và bảng khám phá dưới đây. Các mục khác giữ nhãn population cố định. Phân nhóm mô tả gồm cả OOS tái sử dụng; bins fit in-sample. Giờ/tháng/thứ theo UTC; các phiên dùng múi giờ địa phương.</p><div id="live-overall" class="chart"></div><div id="live-group" class="chart"></div><div id="live-table" class="table-scroll"></div>'
    def grouped(dim,title):
        fig=go.Figure()
        for m in range(5):
            g=[x for x in groups if x['track']=='B' and x['model']==m and x['dimension']==dim]
            fig.add_trace(go.Bar(name=NAMES[m],x=[x['group'] for x in g],y=[100*x['win_rate'] if x['win_rate'] is not None else None for x in g],customdata=[x['resolved'] for x in g],hovertemplate='%{x}<br>WR %{y:.2f}% · n=%{customdata}<extra>%{fullData.name}</extra>'))
        fig.update_yaxes(title='WR (%)');return chart(fig,title)
    sections[7]=grouped('symbol','Track B · công cụ · n trong hover')
    sections[8]=grouped('direction','Track B · bullish / bearish')
    sections[9]=grouped('session_sb','Track B · phiên Silver Bullet')+grouped('session','Track B · phiên thị trường tại confirmation')
    sections[10]=grouped('year','Track B · năm UTC')+'<p>Kết quả từng tháng, thứ và giờ xem bộ lọc tại mục 6. Không chọn tháng/phiên có kết quả cao để sửa tham số.</p>'
    fig=go.Figure(go.Scatter(x=[NAMES[s['model']] for s in b],y=[100*s['win_rate'] if s['win_rate'] is not None else None for s in b],mode='markers',error_y=dict(type='data',symmetric=False,array=[100*(s['wilson']['95']['high']-s['win_rate']) if s['win_rate'] is not None else 0 for s in b],arrayminus=[100*(s['win_rate']-s['wilson']['95']['low']) if s['win_rate'] is not None else 0 for s in b]),customdata=[s['resolved'] for s in b],hovertemplate='%{x}: %{y:.2f}% (n=%{customdata})<extra></extra>'))
    sections[11]=chart(fig,'Track B · Wilson 95% (tham chiếu iid)')+'<p>Overlap, tự tương quan và nhiều mã cùng thời điểm vi phạm độc lập. Dùng thêm bootstrap theo block lịch ở mục 17; CI không chứng minh tính ổn định tương lai.</p>'
    fig=go.Figure()
    for key,label in [('gross','Gross'),('cost_adjusted','Net')]:fig.add_trace(go.Bar(name=label,x=[NAMES[s['model']] for s in b],y=[s[key]['expectancy_r'] for s in b]))
    sections[12]=chart(fig,'Track B · expectancy trên resolved (R)')+'<p>Chi phí R = 0,001 × entry / risk-distance; giả định tổng phí và slippage, không phải phí sàn đã xác minh. Không funding. Risk nhỏ làm chi phí tính theo R rất lớn. Gross win vẫn có thể là net loss.</p>'
    sections[13]=table([{'Track':s['track'],'Mô hình':s['name'],'n resolved':s['resolved'],'PF gross':num(s['gross']['profit_factor']),'PF net':num(s['cost_adjusted']['profit_factor'])} for s in totals])+'<p>PF = tổng R dương / trị tuyệt đối tổng R âm; không có loss thì để trống và tham khảo JSON infinite flag.</p>'
    curve=go.Figure();dd=go.Figure()
    for s in b:
        g=sim[(sim.track=='B')&(sim.model==s['model'])&sim.outcome.isin(['win','loss'])].sort_values('exit_time',kind='stable')
        y=g.net_r.cumsum().to_numpy();d=np.maximum.accumulate(np.r_[0,y])[1:]-y
        ix=np.unique(np.linspace(0,len(g)-1,min(1500,len(g))).astype(int)) if len(g) else []
        curve.add_trace(go.Scatter(x=g.exit_time.iloc[ix],y=y[ix],name=s['name'],mode='lines'))
        dd.add_trace(go.Scatter(x=g.exit_time.iloc[ix],y=d[ix],name=s['name'],mode='lines'))
    sections[14]=chart(curve,'Track B · tổng Net R theo thời gian exit')+'<p>Đường hiển thị lấy tối đa 1.500 điểm mỗi mô hình; bảng thống kê tính trên tất cả quan sát. Tổng R là sổ mô phỏng nhiều quan sát chồng lấn, không phải đường vốn có sizing hay margin thực.</p>'
    sections[15]=chart(dd,'Track B · drawdown từ đỉnh tổng Net R')+table([{'Mô hình':s['name'],'Max DD gross R':num(s['gross']['maximum_drawdown_r']),'Max DD net R':num(s['cost_adjusted']['maximum_drawdown_r']),'Chuỗi loss dài nhất':s['max_consecutive_losses']} for s in b])
    sections[16]='<p>Paired calendar-block bootstrap 7 ngày, cùng lượt resample cho mọi mã và mô hình. Chênh lệch Net E so với M0; CI98,75% Bonferroni cho 4 contrasts mỗi track. Đây là so sánh population khác nhau, không phải tác động nhân quả hay matched-trade. Không suy luận từ WR cao đơn lẻ.</p>'+table([{'Track':track,'Mô hình':NAMES[r['model']],'n mô hình':r['resolved_model'],'n baseline':r['resolved_baseline'],'Delta Net E (R)':num(r['delta_net_expectancy']),'CI98.75%':str([None if x is None else round(x,4) for x in r['ci98_75_bonferroni']])} for track,rs in contrasts.items() for r in rs])+'<p>Phân nhóm nhiều chiều chỉ mô tả; các kiểm định binomial iid/BH trong JSON Track B là thăm dò, không kiểm soát đầy đủ phụ thuộc thời gian. Không áp dụng null WR=1/3 cho Track A có target thay đổi.</p>'
    rows=[]
    for s in totals:
        boot=s.get('bootstrap',{})
        rows.append({'Track':s['track'],'Mô hình':s['name'],'n':s['resolved'],'ESS mô tả':num(boot.get('effective_sample_size'),1),'WR block CI95':str(boot.get('ci',{}).get('95')),'Gross E CI95':str(boot.get('gross_expectancy_ci95')),'Net E CI95':str(boot.get('net_expectancy_ci95'))})
    sections[17]=table(rows)+'<p>1.000 lần lấy mẫu, seed 20261121. Circular blocks giữ ngày không có event. ESS là ước lượng variance-ratio, không phải số giao dịch độc lập đã chứng minh. JSON chứa sensitivity block 1/7/30 ngày.</p>'
    examples='';cache={}
    for m in range(5):
        for direction in ['bullish','bearish']:
            subset=patterns[(patterns.model==m)&(patterns.direction==direction)]
